183	    /**
184	     * Normalize an email to its canonical stored form, which is lower-cased. This is the single
185	     * source of truth for how an email is persisted, so inputs that differ only in letter case
186	     * are stored identically. Applied by {@link #setEmail(String)} so every persistence path
187	     * (create and update, mapper or hand-copied) stores the same canonical value.
188	     *
189	     * @param email the raw email, possibly {@code null}
190	     * @return the lower-cased form, or {@code null} if the input was {@code null}
191	     */
192	    public static String normalizeEmail(String email) {
193	        return email == null ? null : email.toLowerCase();
194	    }
195	
196	    /**
197	     * Normalize a telephone to its canonical E.164 stored form. This is the single source of
198	     * truth for how a telephone is compared and persisted, so inputs that differ only in
199	     * formatting (spaces, dashes, brackets) are treated as the same number.
200	     *
201	     * <p>The rules are:
202	     * <ul>
203	     *   <li>spaces, dashes and brackets are stripped;</li>
204	     *   <li>a leading {@code '+'} and its country code are kept as given;</li>
205	     *   <li>otherwise country code {@code '+61'} is assumed and a single leading {@code '0'}
206	     *       is dropped from the national digits;</li>
207	     *   <li>the result must have 8 to 15 digits after the {@code '+'};</li>
208	     *   <li>for a recognized country code the national number (the digits after the country
209	     *       code) must have the length that code requires: {@code '+61'} requires 9 national
210	     *       digits and {@code '+1'} requires 10.</li>
211	     * </ul>
212	     * For example {@code "0412 345 678"} becomes {@code "+61412345678"}. Already-normalized
213	     * values are returned unchanged.
214	     *
215	     * @param telephone the raw telephone, possibly {@code null}
216	     * @return the E.164 form, or {@code null} if the input is {@code null} or cannot form a
217	     *     valid E.164 number
218	     */
219	    public static String normalizeTelephone(String telephone) {
220	        if (telephone == null) {
221	            return null;
222	        }
223	        String trimmed = telephone.trim();
224	        boolean hasCountryCode = trimmed.startsWith("+");
225	        // Strip spaces, dashes and brackets; a leading '+' (if any) is left in place.
226	        String stripped = trimmed.replaceAll("[\\s\\-()]", "");
227	        if (hasCountryCode) {
228	            stripped = stripped.substring(1);
229	        }
230	        if (!stripped.matches("\\d+")) {
231	            return null;
232	        }
233	        String digits;
234	        if (hasCountryCode) {
235	            digits = stripped;
236	        } else {
237	            if (stripped.startsWith("0")) {
238	                stripped = stripped.substring(1);
239	            }
240	            digits = "61" + stripped;
241	        }
242	        if (digits.length() < 8 || digits.length() > 15) {
243	            return null;
244	        }
245	        if (!hasValidNationalNumberLength(digits)) {
246	            return null;
247	        }
248	        return "+" + digits;
249	    }
250	
251	    /**
252	     * Required national-number length (the count of digits after the country code) for each
253	     * recognized country code, longest country code first so the prefix match is unambiguous.
254	     */
255	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS = new LinkedHashMap<>();
256	    static {
257	        NATIONAL_NUMBER_LENGTHS.put("61", 9);
258	        NATIONAL_NUMBER_LENGTHS.put("1", 10);
259	    }
260	
261	    /**
262	     * Check that the national number of an E.164 digit string (no leading {@code '+'}) has the
263	     * length its country code requires. A country code with no registered length places no
264	     * additional constraint and is accepted.
265	     *
266	     * @param digits the E.164 digits without the leading {@code '+'}
267	     * @return {@code true} if the national-number length is valid for the country code
268	     */
269	    private static boolean hasValidNationalNumberLength(String digits) {
270	        for (Map.Entry<String, Integer> entry : NATIONAL_NUMBER_LENGTHS.entrySet()) {
271	            String countryCode = entry.getKey();
272	            if (digits.startsWith(countryCode)) {
273	                return digits.length() - countryCode.length() == entry.getValue();
274	            }
275	        }
276	        return true;
277	    }
278	
279	    /**
280	     * Common street-type abbreviations expanded by {@link #normalizeAddress(String)}, keyed by the
281	     * upper-cased abbreviation.
282	     */
283	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
284	        "ST", "STREET",
285	        "RD", "ROAD",
286	        "AVE", "AVENUE");
287	
288	    /**
289	     * Normalize an address to its canonical stored form. Leading and trailing whitespace is
290	     * trimmed, internal runs of whitespace are collapsed to a single space, the text is upper-cased,
291	     * and common street-type abbreviations are expanded as whole words ({@code ST}->{@code STREET},
292	     * {@code RD}->{@code ROAD}, {@code AVE}->{@code AVENUE}). This is the single source of truth for
293	     * how an address is persisted and compared, so inputs that differ only in letter case, spacing
294	     * or abbreviation are treated as the same address. Applied by {@link #setAddress(String)} so
295	     * every persistence path (create and update, mapper or hand-copied) stores the same canonical
296	     * value. The transform is idempotent: a normalized address normalizes to itself.
297	     *
298	     * @param address the raw address, possibly {@code null}
299	     * @return the normalized form, or {@code null} if the input was {@code null}
300	     */
301	    public static String normalizeAddress(String address) {
302	        if (address == null) {
303	            return null;
304	        }
305	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase();
306	        if (collapsed.isEmpty()) {
307	            return collapsed;
308	        }
309	        String[] tokens = collapsed.split(" ");
310	        StringBuilder normalized = new StringBuilder(collapsed.length());
311	        for (int i = 0; i < tokens.length; i++) {
312	            if (i > 0) {
313	                normalized.append(' ');
314	            }
315	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
316	        }
317	        return normalized.toString();
318	    }
319	
320	    /**
321	     * Normalize a household field (such as last name or address) to its canonical form for
322	     * duplicate-household comparison. Leading and trailing whitespace is trimmed, internal runs
323	     * of whitespace are collapsed to a single space, and the result is lower-cased, so inputs
324	     * that differ only in letter case or spacing are treated as the same value.
325	     *
326	     * @param value the raw field value, possibly {@code null}
327	     * @return the normalized form, or {@code null} if the input was {@code null}
328	     */
329	    public static String normalizeHousehold(String value) {
330	        if (value == null) {
331	            return null;
332	        }
333	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
334	    }
335	
336	    /**
337	     * Compute the stable identifier shared by all owners in the same household, i.e. with the same
338	     * last name (compared case-insensitively with collapsed whitespace, see
339	     * {@link #normalizeHousehold(String)}) and the same postcode. The value is deterministic in
340	     * those two fields, so two owners who share a last name and postcode are assigned the same id
341	     * automatically. It is formatted {@code 'HH-<HEX12>'} where {@code HEX12} is the first twelve
342	     * upper-cased hex characters of the SHA-256 digest of
343	     * {@code normalizedLastName + '|' + postcode}.
344	     *
345	     * @param lastName the owner's last name, possibly {@code null}
346	     * @param postcode the owner's postcode, possibly {@code null}
347	     * @return the household id, or {@code null} if either field is {@code null}
348	     */
349	    public static String householdId(String lastName, String postcode) {
350	        String normalizedLastName = normalizeHousehold(lastName);
351	        if (normalizedLastName == null || postcode == null) {
352	            return null;
353	        }
354	        String key = normalizedLastName + "|" + postcode;
355	        return "HH-" + sha256Hex(key).substring(0, 12).toUpperCase();
356	    }
357	
358	    /**
359	     * Compute the full lower-case hex SHA-256 digest of the UTF-8 bytes of {@code value}. This is the
360	     * shared primitive behind every hash-derived owner value (the household id and the customer code),
361	     * so they all agree on algorithm and encoding.
362	     *
363	     * @param value the string to digest, never {@code null}
364	     * @return the 64-character lower-case hex digest
365	     */
366	    private static String sha256Hex(String value) {
367	        try {
368	            byte[] digest = MessageDigest.getInstance("SHA-256")
369	                .digest(value.getBytes(StandardCharsets.UTF_8));
370	            StringBuilder hex = new StringBuilder(digest.length * 2);
371	            for (byte b : digest) {
372	                hex.append(String.format("%02x", b));
373	            }
374	            return hex.toString();
375	        } catch (NoSuchAlgorithmException e) {
376	            // SHA-256 is a standard algorithm required to be present on every JVM.
377	            throw new IllegalStateException("SHA-256 not available", e);
378	        }
379	    }
380	
381	    /**
382	     * Build an owner's {@code customerCode}, the stable owner identity assigned once when the owner is
383	     * created. It is formatted {@code '<REGION>-<HASH8>'} where:
384	     * <ul>
385	     *   <li>{@code REGION} is the region code derived from the postcode (see
386	     *       {@link #regionForPostcode(String)}), or {@code 'UNKNOWN'} when the postcode is absent or
387	     *       in no known range, and</li>
388	     *   <li>{@code HASH8} is the first eight upper-cased hex characters of the SHA-256 digest of the
389	     *       normalized telephone (see {@link #normalizeTelephone(String)}) concatenated with the last
390	     *       name.</li>
391	     * </ul>
392	     * The value is deterministic in the postcode, telephone and last name (e.g.
393	     * {@code 'NSW-1A2B3C4D'}); it carries no sequence number.
394	     *
395	     * @param postcode the owner's postcode, possibly {@code null}
396	     * @param telephone the owner's raw telephone, possibly {@code null}
397	     * @param lastName the owner's last name, possibly {@code null}
398	     * @return the customer code, or {@code null} if the telephone or last name is {@code null}
399	     */
400	    public static String customerCode(String postcode, String telephone, String lastName) {
401	        if (telephone == null || lastName == null) {
402	            return null;
403	        }
404	        String region = regionForPostcode(postcode);
405	        if (region == null) {
406	            region = "UNKNOWN";
407	        }
408	        String normalizedTelephone = normalizeTelephone(telephone);
409	        String key = (normalizedTelephone == null ? "" : normalizedTelephone) + lastName;
410	        return region + "-" + sha256Hex(key).substring(0, 8).toUpperCase();
411	    }
412	
413	    /**
414	     * Compute an owner's {@code identityKey}, the single derived value through which all
415	     * duplicate detection is now expressed. It consolidates the three formerly separate
416	     * telephone, email and household duplicate checks into one key, formatted as
417	     * {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}:
418	     * <ul>
419	     *   <li>the normalized telephone (see {@link #normalizeTelephone(String)}),</li>
420	     *   <li>the normalized email (see {@link #normalizeEmail(String)}), or the empty string
421	     *       when no email is present, and</li>
422	     *   <li>the household id (see {@link #householdId(String, String)}).</li>
423	     * </ul>
424	     * A {@code null} component is rendered as the empty string. Two owners are the same identity
425	     * only when their <em>whole</em> keys are equal; because the telephone is part of the key, two
426	     * members of the same household with different telephones have different keys.
427	     *
428	     * @param telephone the owner's raw telephone, possibly {@code null}
429	     * @param email the owner's email, possibly {@code null}
430	     * @param lastName the owner's last name, possibly {@code null}
431	     * @param postcode the owner's postcode, possibly {@code null}
432	     * @return the identity key, never {@code null}
433	     */
434	    public static String identityKey(String telephone, String email, String lastName, String postcode) {
435	        String normalizedTelephone = normalizeTelephone(telephone);
436	        String normalizedEmail = normalizeEmail(email);
437	        String household = householdId(lastName, postcode);
438	        return (normalizedTelephone == null ? "" : normalizedTelephone)
439	            + "|" + (normalizedEmail == null ? "" : normalizedEmail)
440	            + "|" + (household == null ? "" : household);
441	    }
442	
443	    /**
444	     * Build an owner's {@code membershipNumber}, the stable membership identifier derived from the
445	     * owner's own persisted fields. It is formatted {@code '<customerCode>-M<YY>'} where {@code YY}
446	     * is the last two digits of the registration date's year (e.g. {@code 'NSW-1A2B3C4D-M26'}). The
447	     * value is deterministic in those two fields.
448	     *
449	     * @param customerCode the owner's customer code, possibly {@code null}
450	     * @param registrationDate the owner's registration date, possibly {@code null}
451	     * @return the membership number, or {@code null} if either field is {@code null}
452	     */
453	    public static String membershipNumber(String customerCode, LocalDate registrationDate) {
454	        if (customerCode == null || registrationDate == null) {
455	            return null;
456	        }
457	        return String.format("%s-M%02d", customerCode, registrationDate.getYear() % 100);
458	    }
459	
460	    /**
461	     * Build an owner's {@code membershipLevel}, the derived numeric level assigned on create. The
462	     * value starts at 1, gains 1 when an email is present and gains 1 when {@code namesakeCount} is 0,
463	     * and is capped at 3 (level 4 is reserved for tenure). The value is deterministic in those two
464	     * fields.
465	     *
466	     * @param namesakeCount the owner's namesake count, possibly {@code null}
467	     * @param email the owner's email, possibly {@code null}
468	     * @return the membership level, an integer from 1 to 3
469	     */
470	    public static int membershipLevel(Integer namesakeCount, String email) {
471	        int level = 1;
472	        if (email != null && !email.isEmpty()) {
473	            level++;
474	        }
475	        if (namesakeCount != null && namesakeCount == 0) {
476	            level++;
477	        }
478	        return Math.min(level, 3);
479	    }
480	
481	    /**
482	     * Fixed city-to-region table used by {@link #regionForCity(String)} to resolve a city's region
483	     * for postcode validation, keyed by the exact city name.
484	     */
485	    private static final Map<String, String> CITY_REGION = Map.of(
486	        "Sydney", "NSW",
487	        "Melbourne", "VIC",
488	        "Brisbane", "QLD");
489	
490	    /**
491	     * Derive an owner's {@code locality}, the canonical region for the owner, from the {@code REGION}
492	     * segment of the owner's {@code customerCode} (see {@link #customerCode(String, String, String)}).
493	     * Because the customer code's region is itself derived from the postcode, the locality now shares
494	     * the owner's region-and-hash identity: it is the text before the first {@code '-'} of the customer
495	     * code. When the owner has no customer code the locality is {@code 'UNKNOWN'}.
496	     *
497	     * @param customerCode the owner's customer code, possibly {@code null}
498	     * @return the canonical region string, or {@code 'UNKNOWN'} when no customer code is present
499	     */
500	    public static String locality(String customerCode) {
501	        if (customerCode == null) {
502	            return "UNKNOWN";
503	        }
504	        int dash = customerCode.indexOf('-');
505	        return dash < 0 ? customerCode : customerCode.substring(0, dash);
506	    }
507	
508	    /**
509	     * Resolve the canonical region for a city from the fixed {@link #CITY_REGION} table. A city not
510	     * in the table (including {@code null}) resolves to {@code 'UNKNOWN'}.
511	     *
512	     * @param city the owner's city, possibly {@code null}
513	     * @return the matching region, or {@code 'UNKNOWN'} when the city is not in the table
514	     */
515	    private static String regionForCity(String city) {
516	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
517	    }
518	
519	    /**
520	     * Fixed region-to-postcode-range table used by {@link #isPostcodeValidForCity(String, String)}
521	     * and {@link #regionForPostcode(String)}, keyed by the canonical region. Each entry is the
522	     * inclusive low and high bound of the region's valid 4-digit postcodes
523	     * ({@code NSW} 2000-2099, {@code VIC} 3000-3099, {@code QLD} 4000-4099). A region not in this
524	     * table (including {@code 'UNKNOWN'}) places no range constraint.
525	     */
526	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
527	        "NSW", new int[] {2000, 2099},
528	        "VIC", new int[] {3000, 3099},
529	        "QLD", new int[] {4000, 4099});
530	
531	    /**
532	     * Resolve the canonical region whose postcode range contains the given postcode, using the fixed
533	     * {@link #REGION_POSTCODE_RANGES} table. A {@code null} postcode, one that is not exactly four
534	     * digits, or one that falls in no known range resolves to {@code null}.
535	     *
536	     * @param postcode the owner's postcode, possibly {@code null}
537	     * @return the matching region, or {@code null} when no range contains the postcode
538	     */
539	    private static String regionForPostcode(String postcode) {
540	        if (postcode == null || !postcode.matches("\\d{4}")) {
541	            return null;
542	        }
543	        int value = Integer.parseInt(postcode);
544	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGES.entrySet()) {
545	            int[] range = entry.getValue();
546	            if (value >= range[0] && value <= range[1]) {
547	                return entry.getKey();
548	            }
549	        }
550	        return null;
551	    }
552	
553	    /**
554	     * Check whether a postcode is valid for an owner's city. Postcode is optional, so a
555	     * {@code null} or empty postcode is always valid. When present it must be exactly four
556	     * digits, and when the city's region (from the fixed city-to-region table) has a known postcode
557	     * range the value must fall within that inclusive range. A city with no known region accepts
558	     * any four-digit postcode. This is the single source of
559	     * truth for postcode validity, shared by the DTO validation and any persistence path.
560	     *
561	     * @param postcode the owner's postcode, possibly {@code null}
562	     * @param city the owner's city, possibly {@code null}
563	     * @return {@code true} if the postcode is absent or valid for the city, {@code false} otherwise
564	     */
565	    public static boolean isPostcodeValidForCity(String postcode, String city) {
566	        if (postcode == null || postcode.isEmpty()) {
567	            return true;
568	        }
569	        if (!postcode.matches("\\d{4}")) {
570	            return false;
571	        }
572	        int[] range = REGION_POSTCODE_RANGES.get(regionForCity(city));
573	        if (range == null) {
574	            return true;
575	        }
576	        int value = Integer.parseInt(postcode);
577	        return value >= range[0] && value <= range[1];
578	    }
579	
580	    /**
581	     * Compute an owner's {@code checkDigit}, a single Luhn check digit (0-9) over the digits
582	     * contained in the {@code customerCode}. Non-digit characters in the code are ignored. The
583	     * value is deterministic in the customer code and is the standard Luhn check digit: each
584	     * digit is weighted right-to-left, every second digit (starting with the rightmost) is
585	     * doubled with digit sums above nine reduced by nine, and the check digit is the amount that
586	     * brings the weighted sum up to the next multiple of ten.
587	     *
588	     * @param customerCode the owner's customer code, possibly {@code null}
589	     * @return the Luhn check digit from 0 to 9, or {@code null} if the customer code is {@code null}
590	     */
591	    public static Integer checkDigit(String customerCode) {
592	        if (customerCode == null) {
593	            return null;
594	        }
595	        int sum = 0;
596	        boolean dbl = true;
597	        for (int i = customerCode.length() - 1; i >= 0; i--) {
598	            char c = customerCode.charAt(i);
599	            if (c < '0' || c > '9') {
600	                continue;
601	            }
602	            int d = c - '0';
603	            if (dbl) {
604	                d *= 2;
605	                if (d > 9) {
606	                    d -= 9;
607	                }
608	            }
609	            sum += d;
610	            dbl = !dbl;
611	        }
612	        return (10 - (sum % 10)) % 10;
613	    }
614	
615	    /**
616	     * Derive an owner's {@code contactPreference}, the preferred channel for contacting the owner.
617	     * The value is {@code 'EMAIL'} when an email is present and {@code 'PHONE'} otherwise. The value
618	     * is deterministic in the email.
619	     *
620	     * @param email the owner's email, possibly {@code null}
621	     * @return {@code 'EMAIL'} when an email is present, otherwise {@code 'PHONE'}
622	     */
623	    public static String contactPreference(String email) {
624	        return (email != null && !email.isEmpty()) ? "EMAIL" : "PHONE";
625	    }
626	
627	    /**
628	     * Derive an owner's {@code ageBand}, the band the owner's age falls into on the registration
629	     * date. The age in whole years is the number of completed years between {@code birthDate} and
630	     * {@code registrationDate}, and the band is {@code 'MINOR'} when under 18, {@code 'ADULT'} when
631	     * 18 to 64 inclusive, and {@code 'SENIOR'} when 65 or older. The value is deterministic in those
632	     * two fields and is only defined when both are present.
633	     *
634	     * @param birthDate the owner's date of birth, possibly {@code null}
635	     * @param registrationDate the owner's registration date, possibly {@code null}
636	     * @return {@code 'MINOR'}, {@code 'ADULT'} or {@code 'SENIOR'}, or {@code null} when either date
637	     *     is {@code null}
638	     */
639	    public static String ageBand(LocalDate birthDate, LocalDate registrationDate) {
640	        if (birthDate == null || registrationDate == null) {
641	            return null;
642	        }
643	        int age = Period.between(birthDate, registrationDate).getYears();
644	        if (age < 18) {
645	            return "MINOR";
646	        }
647	        if (age < 65) {
648	            return "ADULT";
649	        }
650	        return "SENIOR";
651	    }
652	
653	    protected Set<Pet> getPetsInternal() {
654	        if (this.pets == null) {
655	            this.pets = new HashSet<>();
656	        }
657	        return this.pets;
658	    }
659	
660	    protected void setPetsInternal(Set<Pet> pets) {
661	        this.pets = pets;
662	    }
663	
664	    public List<Pet> getPets() {
665	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
666	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
667	        return Collections.unmodifiableList(sortedPets);
668	    }
669	
670	    public void setPets(List<Pet> pets) {
671	        this.pets = new HashSet<>(pets);
672	    }
673	
674	    public void addPet(Pet pet) {
675	        getPetsInternal().add(pet);
676	        pet.setOwner(this);
677	    }
678	
679	    /**
680	     * Return the Pet with the given name, or null if none found for this Owner.
681	     *
682	     * @param name to test
683	     * @return true if pet name is already in use
684	     */
685	    public Pet getPet(String name) {
686	        return getPet(name, false);
687	    }
688	
689	    /**
690	     * Return the Pet with the given name, or null if none found for this Owner.
691	     *
692	     * @param name to test
693	     * @return true if pet name is already in use
694	     */
695	    public Pet getPet(String name, boolean ignoreNew) {
696	        name = name.toLowerCase();
697	        for (Pet pet : getPetsInternal()) {
698	            if (!ignoreNew || !pet.isNew()) {
699	                String compName = pet.getName();
700	                compName = compName.toLowerCase();
701	                if (compName.equals(name)) {
702	                    return pet;
703	                }
704	            }
705	        }
706	        return null;
707	    }
708	
709	    public Pet getPet(Integer petId) {
710	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
711	    }
712	
713	    @Override
714	    public String toString() {
715	        return new ToStringCreator(this)
716	
717	            .append("id", this.getId())
718	            .append("new", this.isNew())
719	            .append("lastName", this.getLastName())
720	            .append("firstName", this.getFirstName())
721	            .append("address", this.address)
722	            .append("city", this.city)
723	            .append("telephone", this.telephone)
724	            .toString();
725	    }
726	}
